        className
      )}
      disabled={!canScrollNext}
      onClick={scrollNext}
      {...props}
    >
      <ChevronRightIcon
        className="cn-rtl-flip"
       />
      <span className="sr-only">Next slide</span>
    </Button>
  )
}

