import * as React from 'react'

import {
  Accordion as ShadcnAccordion,
  AccordionContent as ShadcnAccordionContent,
  AccordionItem as ShadcnAccordionItem,
  AccordionTrigger as ShadcnAccordionTrigger,
} from '@/components/applique/internal/accordion'

type ShadcnAccordionProps = React.ComponentPropsWithoutRef<
  typeof ShadcnAccordion
>
type ShadcnAccordionItemProps = React.ComponentPropsWithoutRef<
  typeof ShadcnAccordionItem
>
type LegacyIconName = string | React.ReactNode | React.ComponentType<any>

export interface AccordionControlIcons {
  open: LegacyIconName
  close: LegacyIconName
}

export interface AccordionItemProps
  extends Omit<ShadcnAccordionItemProps, 'children' | 'title' | 'value'> {
  /** The always-visible header of the item (legacy `title`). */
  title?: React.ReactNode
  /** Accepted for source compatibility; legacy runtime ignored this override. */
  controlIcons?: AccordionControlIcons
  children?: React.ReactNode
}

/**
 * A single accordion pane. Preserves the legacy `<Accordion.Item title>` API.
 * It is a declarative marker: the root reads `title`/`children` and composes
 * them into the shadcn trigger/content parts, so it renders nothing on its own.
 */
function AccordionItem(_props: AccordionItemProps): React.ReactElement | null {
  return null
}

AccordionItem.displayName = 'Accordion.Item'

export interface AccordionProps
  extends Omit<ShadcnAccordionProps, 'children' | 'multiple' | 'onChange'> {
  /** Accepted while the legacy documented/runtime mismatch is under review. */
  active?: number
  /** Legacy change callback: `(currentIndex, active)`. */
  onChange?(currentIndex: number, active: boolean): void
  /** Replaces the default closed/open trigger icons. */
  controlIcons?: AccordionControlIcons
  children?: React.ReactNode
}

const AccordionRoot = React.forwardRef<HTMLDivElement, AccordionProps>(
  (
    {
      active,
      children,
      controlIcons,
      defaultValue,
      onChange,
      onValueChange: passthroughOnValueChange,
      value,
      ...primitiveProps
    },
    ref
  ) => {
    // The documented `active` prop was never applied by the legacy runtime.
    // Keep accepting it while the contract is reviewed, but do not invent new
    // controlled behavior in this migration batch.
    void active

    const childNodes = React.Children.toArray(children)

    const controlledOpenValues =
      value === undefined ? undefined : normalizeOpenValues(value)

    // Track the real starting state so the first legacy callback can report an
    // accurate open/closed diff for raw value/defaultValue consumers.
    const openRef = React.useRef<number[]>(
      controlledOpenValues ?? normalizeOpenValues(defaultValue)
    )
    if (controlledOpenValues !== undefined) {
      openRef.current = controlledOpenValues
    }

    const handleValueChange: ShadcnAccordionProps['onValueChange'] = (
      nextValue,
      eventDetails
    ) => {
      passthroughOnValueChange?.(nextValue, eventDetails)
      if (eventDetails.isCanceled) return

      const next = nextValue
        .map((value) => Number(value))
        .filter((value) => Number.isInteger(value))
      const nextSet = new Set(next)
      const prevSet = new Set(controlledOpenValues ?? openRef.current)
      if (controlledOpenValues === undefined) openRef.current = next

      if (!onChange) return

      const added = next.filter((value) => !prevSet.has(value))
      added.forEach((index) => onChange(index, true))
      const removed = openRefDiff(prevSet, nextSet)
      removed.forEach((index) => onChange(index, false))
    }

    let itemIndex = 0

    return (
      <ShadcnAccordion
        {...primitiveProps}
        ref={ref}
        value={value}
        defaultValue={defaultValue}
        multiple
        onValueChange={handleValueChange}
      >
        {childNodes.map((child, childIndex) => {
          if (!isAccordionItem(child)) return child

          const index = itemIndex
          itemIndex += 1
          const {
            title,
            children: itemChildren,
            controlIcons: _itemControlIcons,
            ...itemProps
          } = child.props

          return (
            <ShadcnAccordionItem
              {...itemProps}
              key={child.key ?? childIndex}
              value={index}
            >
              <ShadcnAccordionTrigger
                className={
                  controlIcons
                    ? '[&>[data-slot=accordion-trigger-icon]]:hidden'
                    : undefined
                }
              >
                {title}
                {controlIcons ? (
                  <LegacyControlIcons controlIcons={controlIcons} />
                ) : null}
              </ShadcnAccordionTrigger>
              <ShadcnAccordionContent>{itemChildren}</ShadcnAccordionContent>
            </ShadcnAccordionItem>
          )
        })}
      </ShadcnAccordion>
    )
  }
)

AccordionRoot.displayName = 'Accordion'

function isAccordionItem(
  child: React.ReactNode
): child is React.ReactElement<AccordionItemProps> {
  return React.isValidElement(child) && child.type === AccordionItem
}

function LegacyControlIcons({
  controlIcons,
}: {
  controlIcons: AccordionControlIcons
}) {
  return (
    <>
      <span
        aria-hidden="true"
        data-applique-accordion-icon="close"
        className="ml-auto inline-flex group-aria-expanded/accordion-trigger:hidden"
      >
        {renderLegacyIcon(controlIcons.close)}
      </span>
      <span
        aria-hidden="true"
        data-applique-accordion-icon="open"
        className="ml-auto hidden group-aria-expanded/accordion-trigger:inline-flex"
      >
        {renderLegacyIcon(controlIcons.open)}
      </span>
    </>
  )
}

function renderLegacyIcon(icon: LegacyIconName): React.ReactNode {
  return typeof icon === 'function' ? React.createElement(icon) : icon
}

function openRefDiff(prevSet: Set<number>, nextSet: Set<number>): number[] {
  const removed: number[] = []
  prevSet.forEach((value) => {
    if (!nextSet.has(value)) removed.push(value)
  })
  return removed
}

function normalizeOpenValues(values?: unknown[]): number[] {
  if (!values) return []

  return values
    .map((value) => Number(value))
    .filter((value) => Number.isInteger(value))
}

const Accordion = Object.assign(AccordionRoot, { Item: AccordionItem })

export { Accordion, AccordionItem }

'use client'

import * as React from 'react'

import {
  Avatar as InternalAvatar,
  AvatarFallback as InternalAvatarFallback,
} from '@/components/applique/internal/avatar'

type InternalAvatarProps = React.ComponentPropsWithoutRef<typeof InternalAvatar>

export interface AvatarProps extends Omit<InternalAvatarProps, 'size'> {
  /** The name used to generate initials and the default accessible label. */
  name: string
  /** Preserves the existing Applique size vocabulary. */
  size?: 'small' | 'medium' | 'large'
}

const sizeMap = {
  small: 'sm',
  medium: 'default',
  large: 'lg',
} as const

const dimensionMap = {
  small: '16px',
  medium: '32px',
  large: '64px',
} as const

const initialsFontSizeMap = {
  small: '9px',
  medium: '18px',
  large: '36px',
} as const

const letterPattern = /^[a-z\u00c0-\u017f]/i

function makeInitials(name: string) {
  const nameTokens = name.toUpperCase().split(/[\s+-]/)
  const tokens: string[] = []
  let initials = ''

  for (const token of nameTokens) {
    if (!letterPattern.test(token)) break
    tokens.push(token)
  }

  if (tokens.length >= 1) initials += tokens[0].substring(0, 1)

  if (tokens.length >= 2) {
    const firstNonInitial = tokens.slice(1).find((token) => !token.match(/.\./))
    initials += (firstNonInitial || tokens[1]).substring(0, 1)
  }

  return initials
}

const Avatar = React.forwardRef<HTMLElement, AvatarProps>(
  (
    {
      'aria-label': ariaLabel,
      children,
      name,
      role = 'img',
      size,
      style,
      title,
      ...internalProps
    },
    ref
  ) => {
    const normalizedName = name
      .replace(
        /([^ ])([A-Z])/g,
        (_match, first, second) => `${first} ${second}`
      )
      .trim()
    const dimensions = {
      height: size ? dimensionMap[size] : '1em',
      width: size ? dimensionMap[size] : '1em',
    }
    const resolvedStyle: InternalAvatarProps['style'] =
      typeof style === 'function'
        ? (state) => ({ ...dimensions, ...style(state) })
        : { ...dimensions, ...style }

    return (
      <InternalAvatar
        {...internalProps}
        ref={ref}
        aria-label={ariaLabel ?? name}
        role={role}
        size={sizeMap[size ?? 'small']}
        style={resolvedStyle}
        title={title ?? name}
      >
        {children === undefined ? (
          <InternalAvatarFallback
            aria-hidden="true"
            data-test-id="initials"
            style={{ fontSize: size ? initialsFontSizeMap[size] : '0.5625em' }}
          >
            {makeInitials(normalizedName)}
          </InternalAvatarFallback>
        ) : (
          children
        )}
      </InternalAvatar>
    )
  }
)

Avatar.displayName = 'Avatar'

export { Avatar }

'use client'

import * as React from 'react'
import {
  ArrowDownToLineIcon,
  BombIcon,
  CalendarIcon,
  CheckIcon,
  ChevronRightIcon,
  CircleHelpIcon,
  DownloadIcon,
  InfoIcon,
  LoaderCircleIcon,
  ScanBarcodeIcon,
  SearchIcon,
  ThumbsDownIcon,
  ThumbsUpIcon,
} from 'lucide-react'

import { Badge as InternalBadge } from '@/components/applique/internal/badge'
import { cn } from '@/lib/utils'

type InternalBadgeProps = React.ComponentPropsWithoutRef<typeof InternalBadge>
type IconName =
  | string
  | React.ReactNode
  | React.ComponentType<any>
  | React.ExoticComponent<any>
type BadgeType = 'info' | 'success' | 'warning' | 'error'
type BadgeVariant = 'solid' | 'outlined'

const legacyStringIconMap: Record<string, React.ElementType> = {
  'arrow-to-bottom': ArrowDownToLineIcon,
  'barcode-scan': ScanBarcodeIcon,
  bomb: BombIcon,
  calendar: CalendarIcon,
  calender: CalendarIcon,
  check: CheckIcon,
  'chevron-right': ChevronRightIcon,
  download: DownloadIcon,
  info: InfoIcon,
  search: SearchIcon,
  spinner: LoaderCircleIcon,
  spinnersolid: LoaderCircleIcon,
  'thumbs-down': ThumbsDownIcon,
  'thumbs-up': ThumbsUpIcon,
}

const warnedUnknownIconNames = new Set<string>()

function renderStringIcon(name: string): React.ReactNode {
  const normalizedName = name.trim().toLowerCase()
  const IconComponent = legacyStringIconMap[normalizedName]

  if (IconComponent) {
    return <IconComponent data-applique-icon={normalizedName} />
  }

  const environment = (globalThis as typeof globalThis & {
    process?: { env?: { NODE_ENV?: string } }
  }).process?.env?.NODE_ENV

  if (
    environment !== 'production' &&
    !warnedUnknownIconNames.has(normalizedName)
  ) {
    warnedUnknownIconNames.add(normalizedName)
    console.warn(
      `[Applique Badge] Unknown legacy icon "${name}". Rendering the fallback icon.`
    )
  }

  return <CircleHelpIcon data-applique-icon-fallback={normalizedName} />
}

function renderIcon(name: IconName): React.ReactNode {
  let icon: React.ReactNode

  if (typeof name === 'string') {
    icon = renderStringIcon(name)
  } else if (
    typeof name === 'function' ||
    (typeof name === 'object' &&
      name !== null &&
      !React.isValidElement(name) &&
      '$$typeof' in name)
  ) {
    const IconComponent = name as React.ElementType
    icon = <IconComponent />
  } else {
    icon = name
  }

  return (
    <span
      aria-hidden="true"
      className="-ml-1 mr-0.5 inline-flex shrink-0 items-center [&>svg]:size-3"
      data-test-id="icon"
    >
      {icon}
    </span>
  )
}

const internalVariantMap = {
  solid: 'default',
  outlined: 'outline',
} as const

const typeClassNameMap: Record<BadgeType, string> = {
  info:
    'bg-[var(--applique-info-background)] text-[var(--applique-info-foreground)]',
  success:
    'bg-[var(--applique-success-background)] text-[var(--applique-success-foreground)]',
  warning:
    'bg-[var(--applique-warning-background)] text-[var(--applique-warning-foreground)]',
  error:
    'bg-[var(--applique-error-background)] text-[var(--applique-error-foreground)]',
}

const solidBorderClassNameMap: Record<BadgeType, string> = {
  info: 'border-[var(--applique-info-background)]',
  success: 'border-[var(--applique-success-background)]',
  warning: 'border-[var(--applique-warning-background)]',
  error: 'border-[var(--applique-error-background)]',
}

const outlinedBorderClassNameMap: Record<BadgeType, string> = {
  info: 'border-[var(--applique-info-foreground)]',
  success: 'border-[var(--applique-success-foreground)]',
  warning: 'border-[var(--applique-warning-foreground)]',
  error: 'border-[var(--applique-error-foreground)]',
}

const sizeClassNameMap = {
  small: 'h-auto leading-none',
  regular: 'h-auto leading-6',
} as const

export interface BadgeProps
  extends Omit<InternalBadgeProps, 'children' | 'variant'> {
  /** The public legacy API accepts a string label. */
  children: string
  /** Semantic color intent. */
  type?: BadgeType
  /** Fill or outlined presentation. */
  variant?: BadgeVariant
  /** Legacy compact or regular line-height. */
  size?: 'small' | 'regular'
  /** Optional leading legacy icon. */
  icon?: IconName
  /** Adds an accessible dismiss control. */
  onClose?: () => void
}

const Badge = React.forwardRef<HTMLElement, BadgeProps>(
  (
    {
      children,
      className,
      icon,
      onClose,
      render,
      size = 'regular',
      type = 'info',
      variant = 'solid',
      ...internalProps
    },
    ref
  ) => {
    const borderClassName =
      variant === 'outlined'
        ? outlinedBorderClassNameMap[type]
        : solidBorderClassNameMap[type]

    return (
      <InternalBadge
        {...internalProps}
        ref={ref}
        // A dismiss button cannot be nested inside an interactive render root
        // such as an anchor. The Applique onClose contract therefore keeps the
        // legacy div root and takes precedence over the shadcn render extension.
        render={onClose ? <div /> : render ?? <div />}
        variant={internalVariantMap[variant]}
        className={cn(
          className,
          'rounded-xs px-2 py-0.5 text-xs font-normal max-md:text-[10px]',
          typeClassNameMap[type],
          sizeClassNameMap[size],
          borderClassName
        )}
      >
        {icon ? renderIcon(icon) : null}
        {children}
        {onClose ? (
          <button
            type="button"
            aria-label="Close"
            className="-mr-1 ml-0.5 inline-flex size-4 shrink-0 items-center justify-center rounded-xs text-current outline-none focus-visible:ring-2 focus-visible:ring-current/40"
            data-test-id="close"
            onClick={onClose}
          >
            <svg
              aria-hidden="true"
              className="size-2"
              focusable="false"
              viewBox="0 0 352 512"
              xmlns="http://www.w3.org/2000/svg"
            >
              <path
                fill="currentColor"
