> = {
  primary: 'default',
  secondary: 'outline',
  tertiary: 'ghost',
  link: 'link',
  text: 'link',
}

const legacySizeMap: Record<
  Exclude<ButtonLegacySize, 'large'>,
  Exclude<InternalButtonSize, null | undefined>
> = {
  xs: 'icon-xs',
  small: 'sm',
  regular: 'default',
}

const largeButtonClassName =
